cat > /workspace/src/image.cpp <<'EOF'
// Packed image capture, validation and lookup.
//
// The image format is the one described in PROTOCOL.md: eleven stages of
// 128 bit cells holding half (TYPE1/TYPE4) or full (TYPE2/TYPE3/TYPE5) node
// records, an NI pattern dictionary, one NI value vector, and explicit front
// locators for the depth-16 and depth-64 forests.
#include "image.hpp"
#include "addrbits.hpp"
#include "fib.hpp"

#include <algorithm>
#include <cstring>
#include <map>
#include <vector>

// ---------------------------------------------------------------- hex words

std::string image_word_hex(const std::bitset<256>& bits) {
    std::string out(64, '0');
    for (int i = 0; i < 64; ++i) {
        unsigned v = 0;
        for (int b = 0; b < 4; ++b) v |= bits[4 * i + b] ? 1u << b : 0;
        out[63 - i] = "0123456789abcdef"[v];
    }
    return out;
}

std::bitset<256> image_word_from_hex(const std::string& text) {
    if (text.size() != 64) throw std::runtime_error("word length");
    std::bitset<256> out;
    for (int i = 0; i < 64; ++i) {
        char c = text[63 - i];
        unsigned v = (c <= '9') ? c - '0' : c - 'a' + 10;
        if (v > 15) throw std::runtime_error("word hex");
        for (int b = 0; b < 4; ++b) out[4 * i + b] = (v >> b) & 1;
    }
    return out;
}

namespace {

inline int owner_index(int origin) { return origin == 0 ? 0 : (origin == 16 ? 1 : 2); }
inline int owner_max(int origin) { return origin == 0 ? 16 : (origin == 16 ? 64 : 128); }

inline uint64_t rec_bits(const std::bitset<256>& w, int off, int n) {
    uint64_t v = 0;
    for (int i = 0; i < n; ++i) if (w[off + i]) v |= 1ull << i;
    return v;
}

inline void rec_set(std::bitset<256>& w, int off, int n, uint64_t v) {
    for (int i = 0; i < n; ++i) w[off + i] = ((v >> i) & 1ull) != 0;
}

// The 64 bit fragment of an inline prefix record, left aligned relative to the
// forest origin.
inline uint64_t fragment_of(int origin, uint64_t phi, uint64_t plo) {
    if (origin == 0) return phi;
    if (origin == 16) return phi << 16;
    return plo;
}

// Rebuild the normalised prefix value of an inline record.
inline void prefix_from_fragment(int origin, uint64_t reghi, uint64_t frag,
                                 uint64_t& phi, uint64_t& plo) {
    if (origin == 0) { phi = frag; plo = 0; }
    else if (origin == 16) { phi = reghi | (frag >> 16); plo = 0; }
    else { phi = reghi; plo = frag; }
}

// ---------------------------------------------------------- canonical trie

struct BLocal {
    uint8_t l;        // relative length measured from the node depth
    uint32_t hop;
    uint64_t hi, lo;  // normalised prefix value (global length = origin + l)
    int pos;          // NI bitmap position (TYPE1/2/3 only)
};

struct BNode {
    int origin = 0, depth = 0;
    uint64_t reghi = 0, reglo = 0;
    std::vector<BLocal> locals;
    std::vector<std::pair<uint8_t, BNode*> > children;  // sorted by key
    int type = 1, stage = 0;
    uint32_t cell = 0;
    int span = 1;
    bool bulk_root = false;
    uint32_t bulk_base = 0;
    int bulk_stage = 0;
    uint64_t bulk_bitmap = 0;
    uint32_t ni_base = 0;
    int bitmap_id = 0;
    uint64_t bmp = IMAGE_BMP_NULL;
    int owned = 0;
};

struct ImageBuilder {
    std::vector<BNode*> arena;
    BNode* root0 = nullptr;
    std::map<uint64_t, BNode*> roots16, roots64;

    ImageBuilder() {}
    ~ImageBuilder() { for (size_t i = 0; i < arena.size(); ++i) delete arena[i]; }

    BNode* make(int origin, int depth, uint64_t hi, uint64_t lo) {
        BNode* n = new BNode();
        n->origin = origin;
        n->depth = depth;
        n->reghi = hi;
        n->reglo = lo;
        arena.push_back(n);
        return n;
    }

    BNode* child(BNode* n, uint8_t key) {
        size_t lo = 0, hi = n->children.size();
        while (lo < hi) {
            size_t mid = (lo + hi) / 2;
            if (n->children[mid].first < key) lo = mid + 1; else hi = mid;
        }
        if (lo < n->children.size() && n->children[lo].first == key) return n->children[lo].second;
        BNode* c = make(n->origin, n->depth + 6, n->reghi, n->reglo);
        set_bits128(c->reghi, c->reglo, n->depth, 6, key);
        n->children.insert(n->children.begin() + lo, std::make_pair(key, c));
        return c;
    }

    void add(uint8_t len, uint64_t hi, uint64_t lo, uint32_t hop) {
        uint64_t phi, plo;
        top_bits(len, hi, lo, phi, plo);
        BNode* n;
        if (len <= 16) {
            if (root0 == nullptr) root0 = make(0, 0, 0, 0);
            n = root0;
        } else if (len <= 64) {
            uint64_t key = phi >> 48;
            typename std::map<uint64_t, BNode*>::iterator it = roots16.find(key);
            if (it == roots16.end())
                it = roots16.insert(std::make_pair(key, make(16, 16, key << 48, 0))).first;
            n = it->second;
        } else {
            uint64_t key = phi;
            typename std::map<uint64_t, BNode*>::iterator it = roots64.find(key);
            if (it == roots64.end())
                it = roots64.insert(std::make_pair(key, make(64, 64, phi, 0))).first;
            n = it->second;
        }
        while (len >= n->depth + 6) n = child(n, chunk6(phi, plo, n->depth));
        BLocal e;
        e.l = (uint8_t)(len - n->depth);
        e.hop = hop;
        e.hi = phi;
        e.lo = plo;
        e.pos = 0;
        n->locals.push_back(e);
    }

    int assign(BNode* n) {
        int own = (int)n->locals.size();
        for (size_t i = 0; i < n->children.size(); ++i) own += assign(n->children[i].second);
        n->owned = own;
        if (own == 1) n->type = 4;
        else if (own == 2) n->type = 5;
        else {
            int nc = (int)n->children.size();
            n->type = (nc <= 2) ? 1 : (nc <= 6 ? 2 : 3);
        }
        n->stage = 10 - (n->depth - n->origin) / 6;
        return own;
    }

    void collect(BNode* n, std::vector<BNode*>& out) {
        out.push_back(n);
        for (size_t i = 0; i < n->children.size(); ++i) collect(n->children[i].second, out);
    }
};

}  // namespace

// ------------------------------------------------------------------ capture

ImageData build_image(const Fib& fib) {
    ImageBuilder b;
    fib.for_each([&](uint32_t len, uint64_t hi, uint64_t lo, uint32_t hop) {
        if (len <= 128) b.add((uint8_t)len, hi, lo, hop);
    });

    std::vector<BNode*> all;
    if (b.root0) b.assign(b.root0);
    for (typename std::map<uint64_t, BNode*>::iterator it = b.roots16.begin(); it != b.roots16.end(); ++it)
        b.assign(it->second);
    for (typename std::map<uint64_t, BNode*>::iterator it = b.roots64.begin(); it != b.roots64.end(); ++it)
        b.assign(it->second);
    if (b.root0) b.collect(b.root0, all);
    for (typename std::map<uint64_t, BNode*>::iterator it = b.roots16.begin(); it != b.roots16.end(); ++it)
        b.collect(it->second, all);
    for (typename std::map<uint64_t, BNode*>::iterator it = b.roots64.begin(); it != b.roots64.end(); ++it)
        b.collect(it->second, all);

    // Local ordering, node sizes, bulk groups.
    for (size_t i = 0; i < all.size(); ++i) {
        BNode* n = all[i];
        for (size_t k = 0; k < n->locals.size(); ++k) {
            BLocal& e = n->locals[k];
            e.pos = ni_position(e.l, bits128(e.hi, e.lo, n->depth, e.l));
        }
        std::sort(n->locals.begin(), n->locals.end(),
                  [](const BLocal& a, const BLocal& c) { return a.pos < c.pos; });
        n->span = (n->type == 2 || n->type == 3 || n->type == 5) ? 2 : 1;
    }
    for (size_t i = 0; i < all.size(); ++i) {
        BNode* n = all[i];
        if (n->type != 3) continue;
        n->bulk_bitmap = 0;
        for (size_t k = 0; k < n->children.size(); ++k) {
            BNode* c = n->children[k].second;
            c->bulk_root = true;
            c->span = 2;
            n->bulk_bitmap |= 1ull << n->children[k].first;
        }
        n->bulk_stage = n->children.empty() ? 0 : n->children[0].second->stage;
    }

    // Compact per-stage placement: bulk groups first (contiguous two cell
    // slots in increasing key order), then the remaining full slots, then the
    // half slots.  No cell inside [0,cells) is left unused.
    uint32_t cells[RAM_NUM];
    for (int s = 0; s < RAM_NUM; ++s) cells[s] = 0;
    for (size_t i = 0; i < all.size(); ++i) all[i]->cell = 0;
    for (int s = 0; s < RAM_NUM; ++s) {
        uint32_t cur = 0;
        for (size_t i = 0; i < all.size(); ++i) {
            BNode* p = all[i];
            if (p->type != 3 || p->children.empty()) continue;
            if (p->children[0].second->stage != s) continue;
            p->bulk_base = cur;
            for (size_t k = 0; k < p->children.size(); ++k)
                p->children[k].second->cell = cur + 2u * (uint32_t)k;
            cur += 2u * (uint32_t)p->children.size();
        }
        for (size_t i = 0; i < all.size(); ++i) {
            BNode* n = all[i];
            if (n->stage != s || n->bulk_root || n->span != 2) continue;
            n->cell = cur;
            cur += 2;
        }
        for (size_t i = 0; i < all.size(); ++i) {
            BNode* n = all[i];
            if (n->stage != s || n->bulk_root || n->span != 1) continue;
            n->cell = cur;
            cur += 1;
        }
        cells[s] = cur;
    }

    ImageData img;
    img.root.stage = -1;
    img.root.cell = 0;
    if (b.root0) { img.root.stage = b.root0->stage; img.root.cell = b.root0->cell; }
    for (typename std::map<uint64_t, BNode*>::iterator it = b.roots16.begin(); it != b.roots16.end(); ++it)
        img.front16.push_back(ImageFront{it->first, ImageLoc{it->second->stage, it->second->cell}});
    for (typename std::map<uint64_t, BNode*>::iterator it = b.roots64.begin(); it != b.roots64.end(); ++it)
        img.front64.push_back(ImageFront{it->first, ImageLoc{it->second->stage, it->second->cell}});

    // NI pattern dictionary and the single NI value vector.
    std::vector<uint64_t> pats;
    for (size_t i = 0; i < all.size(); ++i) {
        BNode* n = all[i];
        if (n->type > 3) continue;
        uint64_t p = 0;
        for (size_t k = 0; k < n->locals.size(); ++k) p |= 1ull << n->locals[k].pos;
        n->bulk_bitmap = 0;  // already set above for TYPE3; keep it
        pats.push_back(p);
        n->bitmap_id = -1;
        n->ni_base = 0;
    }
    // restore bulk fields (bitmap was reused as scratch above)
    for (size_t i = 0; i < all.size(); ++i) {
        BNode* n = all[i];
        if (n->type != 3) continue;
        n->bulk_bitmap = 0;
        for (size_t k = 0; k < n->children.size(); ++k)
            n->bulk_bitmap |= 1ull << n->children[k].first;
    }
    {
        std::sort(pats.begin(), pats.end());
        pats.erase(std::unique(pats.begin(), pats.end()), pats.end());
        img.bitmaps = pats;
        std::vector<uint32_t> nis;
        for (size_t i = 0; i < all.size(); ++i) {
            BNode* n = all[i];
            if (n->type > 3) continue;
            uint64_t p = 0;
            for (size_t k = 0; k < n->locals.size(); ++k) p |= 1ull << n->locals[k].pos;
            for (size_t k = 0; k < pats.size(); ++k) if (pats[k] == p) { n->bitmap_id = (int)k; break; }
            if (p == 0) continue;
            n->ni_base = (uint32_t)nis.size();
            for (size_t k = 0; k < n->locals.size(); ++k) nis.push_back(n->locals[k].hop);
        }
        img.nexthops.swap(nis);
    }

    for (int s = 0; s < RAM_NUM; ++s) {
        img.cells[s] = cells[s];
        img.banks[s].assign((size_t)((cells[s] + 1) / 2), std::bitset<256>());
    }

    // Node records.  BMP is the global fallback: the longest FIB prefix of
    // length <= node depth matching the whole node region.
    for (size_t i = 0; i < all.size(); ++i) {
        BNode* n = all[i];
        uint32_t hop = 0;
        if (fib.longest_within((uint8_t)n->depth, n->reghi, n->reglo, hop)) n->bmp = hop;

        std::bitset<256> rec;
        int pos = 0;
        rec_set(rec, pos, 3, (uint64_t)n->type); pos += 3;
        rec_set(rec, pos, 22, n->bmp); pos += 22;
        if (n->type == 4 || n->type == 5) {
            int cnt = (n->type == 4) ? 1 : 2;
            for (int k = 0; k < cnt; ++k) {
                const BLocal& e = n->locals[k];
                rec_set(rec, pos, 64, fragment_of(n->origin, e.hi, e.lo)); pos += 64;
                rec_set(rec, pos, 8, e.l); pos += 8;
                rec_set(rec, pos, 22, e.hop); pos += 22;
            }
            rec_set(rec, pos, (n->type == 4) ? 9 : 43, 0);
        } else {
            rec_set(rec, pos, 16, (uint64_t)(n->bitmap_id < 0 ? 0 : n->bitmap_id)); pos += 16;
            rec_set(rec, pos, 22, n->ni_base); pos += 22;
            if (n->type == 3) {
                rec_set(rec, pos, 64, n->bulk_bitmap); pos += 64;
                rec_set(rec, pos, 22, n->bulk_base); pos += 22;
                rec_set(rec, pos, 4, (uint64_t)n->bulk_stage); pos += 4;
                for (int k = 0; k < 3; ++k) { rec_set(rec, pos, 32, 15ull << 6); pos += 32; }
                rec_set(rec, pos, 7, 0);
            } else {
                int nc = (n->type == 1) ? 2 : 6;
                for (int k = 0; k < nc; ++k) {
                    if (k < (int)n->children.size()) {
                        BNode* c = n->children[k].second;
                        uint64_t v = ((uint64_t)c->cell << 10) | ((uint64_t)c->stage << 6) |
                                     (uint64_t)n->children[k].first;
                        rec_set(rec, pos, 32, v);
                    } else {
                        rec_set(rec, pos, 32, 15ull << 6);
                    }
                    pos += 32;
                }
                rec_set(rec, pos, 1, 0);
            }
        }

        std::vector<std::bitset<256> >& bank = img.banks[n->stage];
        size_t row = n->cell >> 1;
        if (n->span == 2) {
            bank[row] = rec;
        } else {
            int off = (int)(n->cell & 1u) * 128;
            for (int k = 0; k < 128; ++k) bank[row][off + k] = rec[k];
        }
    }
    return img;
}

// ---------------------------------------------------------------- validation

namespace {

struct LoadCtx {
    const ImageData& d;
    std::vector<ImageNode> nodes;
    std::vector<std::vector<int> > slot;
    std::vector<std::vector<uint8_t> > used;
    std::vector<uint8_t> ni_used;
    std::vector<uint8_t> pat_used;
    int root_idx;
    std::vector<std::pair<uint32_t, int> > f16, f64;
    bool ok;

    explicit LoadCtx(const ImageData& dd) : d(dd), root_idx(-1), ok(true) {}

    // Returns the node index, or -1 after recording a violation.
    int decode(int stage, uint32_t cell, int origin, int depth,
               uint64_t reghi, uint64_t reglo, bool bulk) {
        if (!ok) return -1;
        if (stage < 0 || stage >= RAM_NUM) { ok = false; return -1; }
        if (cell >= d.cells[stage]) { ok = false; return -1; }
        if ((int)d.banks[stage].size() != (int)((d.cells[stage] + 1) / 2)) { ok = false; return -1; }
        if (depth > owner_max(origin)) { ok = false; return -1; }
        const std::bitset<256>& w = d.banks[stage][cell >> 1];
        int off = (int)(cell & 1u) * 128;
        int type = (int)rec_bits(w, off, 3);
        if (type < 1 || type > 5) { ok = false; return -1; }
        int span = (type == 2 || type == 3 || type == 5) ? 2 : 1;
        if (span == 2 && (cell & 1u)) { ok = false; return -1; }
        if (bulk && (cell & 1u)) { ok = false; return -1; }
        if (cell + span > d.cells[stage]) { ok = false; return -1; }
        if (used[stage][cell] || (span == 2 && used[stage][cell + 1])) { ok = false; return -1; }
        if (slot[stage][cell] >= 0) { ok = false; return -1; }

        std::bitset<256> rec;
        for (int k = 0; k < span * 128; ++k) rec[k] = w[off + k];

        int idx = (int)nodes.size();
        nodes.push_back(ImageNode());
        slot[stage][cell] = idx;
        used[stage][cell] = 1;
        if (span == 2) used[stage][cell + 1] = 1;

        nodes[idx].type = type;
        nodes[idx].origin = origin;
        nodes[idx].depth = depth;
        nodes[idx].stage = stage;
        nodes[idx].reghi = reghi;
        nodes[idx].reglo = reglo;
        nodes[idx].bmp = rec_bits(rec, 3, 22);

        const int maxlen = owner_max(origin);
        const int lmin = std::max(origin ? 1 : 0, depth - origin);
        std::vector<int> kids;

        if (type == 4 || type == 5) {
            const int base[2] = {25, 119};
            const int cnt = (type == 4) ? 1 : 2;
            for (int k = 0; k < cnt; ++k) {
                uint64_t frag = rec_bits(rec, base[k], 64);
                int l = (int)rec_bits(rec, base[k] + 64, 8);
                uint32_t hop = (uint32_t)rec_bits(rec, base[k] + 72, 22);
                if (hop >= IMAGE_BMP_NULL) { ok = false; return -1; }
                if (l < lmin || l > maxlen - origin) { ok = false; return -1; }
                if (l < 64 && (frag & ((1ull << (64 - l)) - 1))) { ok = false; return -1; }
                uint64_t phi, plo, thi, tlo;
                prefix_from_fragment(origin, reghi, frag, phi, plo);
                top_bits(depth, phi, plo, thi, tlo);
                if (thi != reghi || tlo != reglo) { ok = false; return -1; }
                ImageNode::Pfx p;
                p.l = (uint8_t)l;
                p.hop = hop;
                p.hi = phi;
                p.lo = plo;
                nodes[idx].inlines.push_back(p);
            }
            if (type == 5) {
                const ImageNode::Pfx& a = nodes[idx].inlines[0];
                const ImageNode::Pfx& b = nodes[idx].inlines[1];
                if (a.l == b.l && a.hi == b.hi && a.lo == b.lo) { ok = false; return -1; }
            }
            rec_set_check(idx, rec, (type == 4) ? 119 : 213, (type == 4) ? 9 : 43);
            if (!ok) return -1;
        } else {
            int bid = (int)rec_bits(rec, 25, 16);
            if (bid >= (int)d.bitmaps.size()) { ok = false; return -1; }
            nodes[idx].pattern = d.bitmaps[bid];
            pat_used[bid] = 1;
            nodes[idx].ni_base = (uint32_t)rec_bits(rec, 41, 22);
            nodes[idx].ni_count = __builtin_popcountll(nodes[idx].pattern);
            if (nodes[idx].pattern & 1ull) { ok = false; return -1; }
            const int maxl = std::min(5, maxlen - depth);
            if (nodes[idx].ni_count == 0) {
                if (nodes[idx].ni_base != 0) { ok = false; return -1; }
            } else {
                if ((uint64_t)nodes[idx].ni_base + (uint64_t)nodes[idx].ni_count >
                    d.nexthops.size()) { ok = false; return -1; }
                for (int k = 0; k < nodes[idx].ni_count; ++k) {
                    if (ni_used[nodes[idx].ni_base + k]) { ok = false; return -1; }
                    ni_used[nodes[idx].ni_base + k] = 1;
                }
            }
            uint64_t p = nodes[idx].pattern;
            while (p) {
                int b = __builtin_ctzll(p);
                p &= p - 1ull;
                if (ni_level(b) > maxl) { ok = false; return -1; }
            }
            if (type == 1) {
                if (rec_bits(rec, 127, 1) != 0) { ok = false; return -1; }
                int present = 0;
                uint8_t last = 0;
                bool seen_absent = false;
                for (int k = 0; k < 2; ++k) {
                    uint32_t raw = (uint32_t)rec_bits(rec, 63 + 32 * k, 32);
                    if (raw == (15u << 6)) { seen_absent = true; continue; }
                    if (seen_absent) { ok = false; return -1; }
                    uint8_t key = (uint8_t)(raw & 0x3F);
                    int cst = (int)((raw >> 6) & 0xF);
                    uint32_t ccell = (raw >> 10) & 0x3FFFFF;
                    if (cst > 10 || cst >= stage) { ok = false; return -1; }
                    if (present && key <= last) { ok = false; return -1; }
                    last = key;
                    ++present;
                    if (depth + 6 > maxlen) { ok = false; return -1; }
                    ImageNode::Child c;
                    c.key = key; c.stage = cst; c.cell = ccell;
                    nodes[idx].children.push_back(c);
                    uint64_t chi = reghi, clo = reglo;
                    set_bits128(chi, clo, depth, 6, key);
                    int ci = decode(cst, ccell, origin, depth + 6, chi, clo, false);
                    if (ci < 0) return -1;
                    kids.push_back(ci);
                }
            } else if (type == 2) {
                if (rec_bits(rec, 255, 1) != 0) { ok = false; return -1; }
                int present = 0;
                uint8_t last = 0;
                bool seen_absent = false;
                for (int k = 0; k < 6; ++k) {
                    uint32_t raw = (uint32_t)rec_bits(rec, 63 + 32 * k, 32);
                    if (raw == (15u << 6)) { seen_absent = true; continue; }
                    if (seen_absent) { ok = false; return -1; }
                    uint8_t key = (uint8_t)(raw & 0x3F);
                    int cst = (int)((raw >> 6) & 0xF);
                    uint32_t ccell = (raw >> 10) & 0x3FFFFF;
                    if (cst > 10 || cst >= stage) { ok = false; return false; }
                    if (present && key <= last) { ok = false; return -1; }
                    last = key;
                    ++present;
                    if (depth + 6 > maxlen) { ok = false; return -1; }
                    ImageNode::Child c;
                    c.key = key; c.stage = cst; c.cell = ccell;
                    nodes[idx].children.push_back(c);
                    uint64_t chi = reghi, clo = reglo;
                    set_bits128(chi, clo, depth, 6, key);
                    int ci = decode(cst, ccell, origin, depth + 6, chi, clo, false);
                    if (ci < 0) return -1;
                    kids.push_back(ci);
                }
                if (present < 3) { ok = false; return -1; }
            } else {  // TYPE3
                if (rec_bits(rec, 249, 7) != 0) { ok = false; return -1; }
                nodes[idx].bulk_bitmap = rec_bits(rec, 63, 64);
                nodes[idx].bulk_base = (uint32_t)rec_bits(rec, 127, 22);
                int bstage = (int)rec_bits(rec, 149, 4);
                if (bstage > 10 || bstage >= stage) { ok = false; return -1; }
                if (nodes[idx].bulk_base & 1u) { ok = false; return -1; }
                int b = __builtin_popcountll(nodes[idx].bulk_bitmap);
                int present = 0;
                uint8_t last = 0;
                bool seen_absent = false;
                for (int k = 0; k < 3; ++k) {
                    uint32_t raw = (uint32_t)rec_bits(rec, 153 + 32 * k, 32);
                    if (raw == (15u << 6)) { seen_absent = true; continue; }
                    if (seen_absent) { ok = false; return -1; }
                    uint8_t key = (uint8_t)(raw & 0x3F);
                    int cst = (int)((raw >> 6) & 0xF);
                    uint32_t ccell = (raw >> 10) & 0x3FFFFF;
                    if (cst > 10 || cst >= stage) { ok = false; return -1; }
                    if (present && key <= last) { ok = false; return -1; }
                    if ((nodes[idx].bulk_bitmap >> key) & 1ull) { ok = false; return -1; }
                    last = key;
                    ++present;
                    ImageNode::Child c;
                    c.key = key; c.stage = cst; c.cell = ccell;
                    nodes[idx].children.push_back(c);
                }
                if (b + present < 7 || b + present > 64) { ok = false; return -1; }
                if ((uint64_t)nodes[idx].bulk_base + 2ull * (uint64_t)b > d.cells[bstage]) {
                    ok = false; return -1;
                }
                if (depth + 6 > maxlen) { ok = false; return -1; }
                int rank = 0;
                for (int v = 0; v < 64; ++v) {
                    if (!((nodes[idx].bulk_bitmap >> v) & 1ull)) continue;
                    uint32_t ccell = nodes[idx].bulk_base + 2u * (uint32_t)rank;
                    uint64_t chi = reghi, clo = reglo;
                    set_bits128(chi, clo, depth, 6, (uint64_t)v);
                    int ci = decode(bstage, ccell, origin, depth + 6, chi, clo, true);
                    if (ci < 0) return -1;
                    kids.push_back(ci);
                    ++rank;
                }
                for (size_t k = 0; k < nodes[idx].children.size(); ++k) {
                    uint64_t chi = reghi, clo = reglo;
                    set_bits128(chi, clo, depth, 6, nodes[idx].children[k].key);
                    int ci = decode(nodes[idx].children[k].stage, nodes[idx].children[k].cell,
                                    origin, depth + 6, chi, clo, false);
                    if (ci < 0) return -1;
                    kids.push_back(ci);
                }
            }
        }

        int own = (int)nodes[idx].inlines.size();
        if (type <= 3) own += nodes[idx].ni_count;
        for (size_t k = 0; k < kids.size(); ++k) own += nodes[kids[k]].owned;
        nodes[idx].owned = own;
        if (own <= 0) { ok = false; return -1; }
        if (own == 1 && type != 4) { ok = false; return -1; }
        if (own == 2 && type != 5) { ok = false; return -1; }
        if (own >= 3 && type > 3) { ok = false; return -1; }
        return idx;
    }

    void rec_set_check(int, const std::bitset<256>& rec, int off, int n) {
        if (rec_bits(rec, off, n) != 0) ok = false;
    }
};

}  // namespace

bool MemoryImage::load(const ImageData& proposed) {
    // Shape and vector bounds (the front end checks most of this already).
    uint32_t total_cells = 0;
    for (int s = 0; s < RAM_NUM; ++s) {
        if (proposed.cells[s] > 131072u) return false;
        if ((int)proposed.banks[s].size() != (int)((proposed.cells[s] + 1) / 2)) return false;
        total_cells += proposed.cells[s];
    }
    if (total_cells > 131072u) return false;
    if (proposed.bitmaps.size() > 8193u || proposed.nexthops.size() > 8192u) return false;
    for (size_t i = 0; i < proposed.bitmaps.size(); ++i) {
        if (i && proposed.bitmaps[i - 1] >= proposed.bitmaps[i]) return false;
    }
    if (proposed.root.stage < -1 || proposed.root.stage > 10) return false;
    if (proposed.root.stage < 0 && proposed.root.cell != 0) return false;

    LoadCtx ctx(proposed);
    ctx.slot.resize(RAM_NUM);
    ctx.used.resize(RAM_NUM);
    for (int s = 0; s < RAM_NUM; ++s) {
        ctx.slot[s].assign(proposed.cells[s], -1);
        ctx.used[s].assign(proposed.cells[s], 0);
    }
    ctx.ni_used.assign(proposed.nexthops.size(), 0);
    ctx.pat_used.assign(proposed.bitmaps.size(), 0);

    if (proposed.root.stage >= 0) {
        int i = ctx.decode(proposed.root.stage, proposed.root.cell, 0, 0, 0, 0, false);
        if (i < 0) return false;
        ctx.root_idx = i;
    }
    for (size_t i = 0; i < proposed.front16.size(); ++i) {
        const ImageFront& f = proposed.front16[i];
        uint64_t reghi = (f.key & 0xFFFFull) << 48;
        int idx = ctx.decode(f.loc.stage, f.loc.cell, 16, 16, reghi, 0, false);
        if (idx < 0) return false;
        if (i && proposed.front16[i - 1].key >= f.key) return false;
        ctx.f16.push_back(std::make_pair((uint32_t)f.key, idx));
    }
    for (size_t i = 0; i < proposed.front64.size(); ++i) {
        const ImageFront& f = proposed.front64[i];
        int idx = ctx.decode(f.loc.stage, f.loc.cell, 64, 64, f.key, 0, false);
        if (idx < 0) return false;
        if (i && proposed.front64[i - 1].key >= f.key) return false;
        ctx.f64.push_back(std::make_pair((uint32_t)f.key, idx));
    }
    if (!ctx.ok) return false;

    // Dense, non overlapping coverage of every charged slot.
    for (int s = 0; s < RAM_NUM; ++s) {
        size_t cnt = 0;
        for (size_t c = 0; c < ctx.used[s].size(); ++c) cnt += ctx.used[s][c];
        if (cnt != proposed.cells[s]) return false;
        if (proposed.cells[s] & 1u) {
            const std::bitset<256>& w = proposed.banks[s][proposed.cells[s] >> 1];
            for (int k = 128; k < 256; ++k) if (w[k]) return false;
        }
    }
    // Dictionary and NI vector usage.
    for (size_t i = 0; i < ctx.pat_used.size(); ++i) if (!ctx.pat_used[i]) return false;
    for (size_t i = 0; i < ctx.ni_used.size(); ++i) if (!ctx.ni_used[i]) return false;

    // Rebuild the FIB represented by the image and check every BMP.
    Fib fib;
    uint64_t total = 0;
    for (size_t i = 0; i < ctx.nodes.size(); ++i) {
        const ImageNode& n = ctx.nodes[i];
        for (size_t k = 0; k < n.inlines.size(); ++k) {
            fib.put((uint8_t)(n.origin + n.inlines[k].l), n.inlines[k].hi, n.inlines[k].lo,
                    n.inlines[k].hop);
            ++total;
        }
        if (n.type <= 3) {
            uint64_t p = n.pattern;
            while (p) {
                int b = __builtin_ctzll(p);
                p &= p - 1ull;
                int l = ni_level(b);
                uint64_t v = (uint64_t)b - (1ull << l);
                uint64_t phi = n.reghi, plo = n.reglo;
                set_bits128(phi, plo, n.depth, l, v);
                int off = __builtin_popcountll(n.pattern & (((uint64_t)1 << b) - 1));
                fib.put((uint8_t)(n.depth + l), phi, plo, proposed.nexthops[n.ni_base + off]);
                ++total;
            }
        }
    }
    if (total != fib.size()) return false;  // duplicated prefixes
    if (fib.size() > 8192u) return false;
    for (size_t i = 0; i < ctx.nodes.size(); ++i) {
        const ImageNode& n = ctx.nodes[i];
        uint32_t hop = 0;
        uint64_t want = fib.longest_within((uint8_t)n.depth, n.reghi, n.reglo, hop)
                            ? (uint64_t)hop : IMAGE_BMP_NULL;
        if (n.bmp != want) return false;
    }

    data_ = proposed;
    nodes_.swap(ctx.nodes);
    slots_.swap(ctx.slot);
    root_idx_ = ctx.root_idx;
    front16_.swap(ctx.f16);
    front64_.swap(ctx.f64);
    return true;
}

// -------------------------------------------------------------------- lookup

int MemoryImage::find_front(const std::vector<std::pair<uint32_t,int> >& v, uint64_t key) const {
    size_t lo = 0, hi = v.size();
    while (lo < hi) {
        size_t mid = (lo + hi) / 2;
        if (v[mid].first < key) lo = mid + 1; else hi = mid;
    }
    if (lo < v.size() && v[lo].first == key) return v[lo].second;
    return -1;
}

nexthop_t MemoryImage::walk(int idx, uint64_t cursor) const {
    const ImageNode& n = nodes_[idx];
    if (n.type == 4 || n.type == 5) {
        int best_l = -1;
        uint32_t best_hop = 0;
        for (size_t k = 0; k < n.inlines.size(); ++k) {
            const ImageNode::Pfx& p = n.inlines[k];
            bool m = (p.l == 0) ? true : ((cursor >> (64 - p.l)) == (p.hi >> (64 - p.l)));
            if (m && (int)p.l > best_l) { best_l = p.l; best_hop = p.hop; }
        }
        if (best_l >= 0) return best_hop;
        return (n.bmp == IMAGE_BMP_NULL) ? LPM_INVALID_NH : (nexthop_t)n.bmp;
    }
    const int t = (n.depth - n.origin) / 6;
    const uint64_t chunk = (cursor >> (58 - 6 * t)) & 0x3Full;
    for (size_t k = 0; k < n.children.size(); ++k)
        if (n.children[k].key == chunk)
            return walk(slots_[n.children[k].stage][n.children[k].cell], cursor);
    if (n.type == 3 && ((n.bulk_bitmap >> chunk) & 1ull)) {
        int rank = __builtin_popcountll(n.bulk_bitmap & ((1ull << chunk) - 1ull));
        uint32_t cell = n.bulk_base + 2u * (uint32_t)rank;
        return walk(slots_[n.bulk_stage][cell], cursor);
    }
    for (int l = 5; l >= 0; --l) {
        int p = (1 << l) + (int)(chunk >> (6 - l));
        if ((n.pattern >> p) & 1ull) {
            int off = __builtin_popcountll(n.pattern & (((uint64_t)1 << p) - 1ull));
            return data_.nexthops[n.ni_base + off];
        }
    }
    return (n.bmp == IMAGE_BMP_NULL) ? LPM_INVALID_NH : (nexthop_t)n.bmp;
}

nexthop_t MemoryImage::lookup(ip6_t ip) const {
    if (!front64_.empty()) {
        int i = find_front(front64_, ip.hi);
        if (i >= 0) return walk(i, ip.lo);
    }
    if (!front16_.empty()) {
        int i = find_front(front16_, ip.hi >> 48);
        if (i >= 0) return walk(i, ip.hi << 16);
    }
    if (root_idx_ >= 0) return walk(root_idx_, ip.hi);
    return LPM_INVALID_NH;
}
